create type public.governance_case_type as enum ('grievance','appeal','fairness_review','security_incident','data_request');
create table public.program_memberships(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('program_admin','analyst','auditor','grievance_officer','viewer')),status text not null default 'invited' check(status in ('invited','active','suspended')),unique(organization_id,user_id));
create table public.governance_cases(id uuid primary key default gen_random_uuid(),program_organization_id uuid not null references public.organizations(id),case_type public.governance_case_type not null,severity text not null check(severity in ('low','medium','high','critical')),status text not null default 'open' check(status in ('open','investigating','resolved','dismissed')),subject_ref text,summary text not null,assigned_to uuid references auth.users(id),due_at timestamptz,resolution text,created_at timestamptz not null default now(),resolved_at timestamptz);
create table public.model_releases(id uuid primary key default gen_random_uuid(),model_key text not null,version text not null,purpose text not null,provider text not null,evaluation_summary jsonb not null,risk_level text not null check(risk_level in ('low','medium','high')),approved_by uuid references auth.users(id),approved_at timestamptz,status text not null check(status in ('draft','evaluation','approved','retired')),unique(model_key,version));
create table public.aggregate_metric_snapshots(id uuid primary key default gen_random_uuid(),program_organization_id uuid not null references public.organizations(id),geography_level text not null check(geography_level in ('state','district','block')),geography_code text not null,metric_key text not null,metric_value numeric not null,cohort_size integer not null,period_start date not null,period_end date not null,dimensions jsonb not null default '{}',suppressed boolean generated always as (cohort_size<10) stored,unique(program_organization_id,geography_code,metric_key,period_start,period_end,dimensions));
create table public.data_export_requests(id uuid primary key default gen_random_uuid(),program_organization_id uuid not null references public.organizations(id),requested_by uuid not null references auth.users(id),purpose text not null,fields text[] not null,filters jsonb not null default '{}',status text not null default 'pending' check(status in ('pending','approved','rejected','ready','expired')),approved_by uuid references auth.users(id),expires_at timestamptz,download_count integer not null default 0,created_at timestamptz not null default now());
create table public.audit_events(id bigint generated always as identity primary key,actor_user_id uuid references auth.users(id),organization_id uuid references public.organizations(id),action text not null,resource_type text not null,resource_id text,purpose text,metadata jsonb not null default '{}',created_at timestamptz not null default now());
alter table public.program_memberships enable row level security;alter table public.governance_cases enable row level security;alter table public.model_releases enable row level security;alter table public.aggregate_metric_snapshots enable row level security;alter table public.data_export_requests enable row level security;alter table public.audit_events enable row level security;
create function public.is_active_program_member(org uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.program_memberships m where m.organization_id=org and m.user_id=auth.uid() and m.status='active')$$;
create policy "program members read membership" on public.program_memberships for select using(user_id=auth.uid() or public.is_active_program_member(organization_id));
create policy "members manage governance cases" on public.governance_cases for all using(public.is_active_program_member(program_organization_id)) with check(public.is_active_program_member(program_organization_id));
create policy "approved model cards readable" on public.model_releases for select using(status='approved' or approved_by=auth.uid());
create policy "members read unsuppressed aggregates" on public.aggregate_metric_snapshots for select using(not suppressed and public.is_active_program_member(program_organization_id));
create policy "members request exports" on public.data_export_requests for insert with check(requested_by=auth.uid() and public.is_active_program_member(program_organization_id));
create policy "members read own exports" on public.data_export_requests for select using(requested_by=auth.uid() or public.is_active_program_member(program_organization_id));
create policy "members read scoped audit" on public.audit_events for select using(organization_id is not null and public.is_active_program_member(organization_id));
create index governance_cases_queue_idx on public.governance_cases(program_organization_id,status,due_at);create index aggregate_metrics_lookup_idx on public.aggregate_metric_snapshots(program_organization_id,metric_key,period_end);create index audit_events_org_time_idx on public.audit_events(organization_id,created_at desc);
